<script setup>import AppShell from'../../Layouts/AppShell.vue';import{Head,Link}from'@inertiajs/vue3';const p=defineProps({payment:Object}),success=p.payment.status==='paid',processing=['created','processing'].includes(p.payment.status),failed=p.payment.status==='failed',title=success?'Payment successful':processing?'Payment processing':failed?'Payment failed':'Payment cancelled',message=success?'Your LensPic subscription is now active.':processing?'We are securely confirming your payment. Refresh this page shortly.':failed?'The payment was rejected and no subscription was activated.':'Checkout was closed before payment completed.'</script>
<template><AppShell><Head :title="title"/><main class="mx-auto flex min-h-[calc(100vh-8rem)] max-w-3xl items-center justify-center py-8"><section class="lp-card w-full overflow-hidden p-6 text-center sm:p-10" aria-live="polite"><div :class="['mx-auto grid h-16 w-16 place-items-center rounded-full text-3xl font-bold',success?'bg-emerald-100 text-emerald-700':processing?'bg-amber-100 text-amber-700':'bg-rose-100 text-rose-700']" aria-hidden="true">{{success?'✓':processing?'…':'!'}}</div><h1 class="mt-5 text-3xl font-bold text-slate-950">{{title}}</h1><p class="mt-2 text-slate-600">{{message}}</p><dl class="mt-8 grid gap-x-8 gap-y-4 border-y border-slate-200 py-6 text-left sm:grid-cols-2"><div><dt class="text-xs font-semibold uppercase tracking-wide text-slate-500">Plan</dt><dd class="mt-1 font-semibold">{{payment.plan}}</dd></div><div><dt class="text-xs font-semibold uppercase tracking-wide text-slate-500">Billing cycle</dt><dd class="mt-1 font-semibold">{{payment.billing_cycle}}</dd></div><div><dt class="text-xs font-semibold uppercase tracking-wide text-slate-500">Base price</dt><dd class="mt-1">{{payment.base_amount}}</dd></div><div><dt class="text-xs font-semibold uppercase tracking-wide text-slate-500">GST</dt><dd class="mt-1">{{payment.gst_amount}}</dd></div><div><dt class="text-xs font-semibold uppercase tracking-wide text-slate-500">Total paid</dt><dd class="mt-1 text-lg font-bold">{{payment.total_amount}}</dd></div><div><dt class="text-xs font-semibold uppercase tracking-wide text-slate-500">Status</dt><dd class="mt-1 capitalize">{{success?'Paid':payment.status}}</dd></div><div><dt class="text-xs font-semibold uppercase tracking-wide text-slate-500">LensPic reference</dt><dd class="mt-1 break-all font-mono text-sm">{{payment.reference}}</dd></div><div v-if="payment.payment_id"><dt class="text-xs font-semibold uppercase tracking-wide text-slate-500">Razorpay payment ID</dt><dd class="mt-1 break-all font-mono text-sm">{{payment.payment_id}}</dd></div><div v-if="payment.payment_at"><dt class="text-xs font-semibold uppercase tracking-wide text-slate-500">Payment date</dt><dd class="mt-1">{{new Date(payment.payment_at).toLocaleString('en-IN')}}</dd></div><div v-if="payment.activation_at"><dt class="text-xs font-semibold uppercase tracking-wide text-slate-500">Activated</dt><dd class="mt-1">{{new Date(payment.activation_at).toLocaleString('en-IN')}}</dd></div><div v-if="payment.expires_at"><dt class="text-xs font-semibold uppercase tracking-wide text-slate-500">Expiry / renewal</dt><dd class="mt-1">{{new Date(payment.expires_at).toLocaleString('en-IN')}}</dd></div><div v-if="payment.failure_reason"><dt class="text-xs font-semibold uppercase tracking-wide text-slate-500">Reason</dt><dd class="mt-1 text-rose-700">{{payment.failure_reason}}</dd></div></dl><div class="mt-7 flex flex-col justify-center gap-3 sm:flex-row"><Link :href="payment.dashboard_url" class="btn-primary">Go to Dashboard</Link><Link :href="payment.subscription_url" class="btn-ghost">View Subscription</Link><a v-if="payment.receipt_url" :href="payment.receipt_url" target="_blank" rel="noopener" class="btn-ghost">Download Receipt</a></div></section></main></AppShell></template>
<style scoped>@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto!important;transition:none!important}}</style>
